vocab={'train','ing','older','model','models','new','knowledge'}
word='training'
def greedy_pieces(w):
    result=[]
    while w:
        piece=max((t for t in vocab if w.startswith(t)),key=len,default=w[0])
        result.append(piece); w=w[len(piece):]
    return result
print(greedy_pieces(word))  # illustrative, not actual BPE

