from time import perf_counter
# Illustrative cache keyed by token prefix, not a transformer KV cache
cache={}
def expensive(prefix): return sum(i*i for i in range(20000))+len(prefix)
for prefix in ['a','ab','abc','ab','abc']:
    t=perf_counter()
    if prefix not in cache: cache[prefix]=expensive(prefix)
    print(prefix,'cached value',cache[prefix],'elapsed',round(perf_counter()-t,5))

